from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class ScriptRunnerReason(SchemaObject):
    error_str = SchemaField(name='error_str', not_null=True)
    target_type = SchemaField(name='target_type', not_null=True)
    target = SchemaField(name='target', many=True, not_null=True)

    def __init__(self, error_str, target_type, target):
        self.error_str = error_str
        self.target_type = target_type
        self.target = target

        super(ScriptRunnerReason, self).__init__()


class M2MScriptRunnerResponseV1(SchemaObject):
    operation_id = SchemaField(name="operation_id", not_null=True)
    error_message = SchemaField(name="error_message", klass=ScriptRunnerReason, many=True, optional=True)
    status = SchemaField(name="status", not_null=True)
    new_file_generated = SchemaField(name='new_file_generated', not_null=True)

    def __init__(self, operation_id, error_message, status, new_file_generated):
        self.operation_id = operation_id
        self.error_message = error_message
        self.new_file_generated = new_file_generated
        self.status = status

        super(M2MScriptRunnerResponseV1, self).__init__()
